import pytest

from bedrock_protocol import v975, v1001

# generated by gophertunnel e76ee66:
# packet.SubChunkRequest{Dimension: 0, Position: protocol.SubChunkPos{1, 2, 3},
#   Offsets: []protocol.SubChunkOffset{{-1, 0, 1}}}
V975 = bytes.fromhex("0002040601000000ff0001")

# generated by gophertunnel 6353c49:
# packet.SubChunkRequest{Dimension: 0, Position: protocol.SubChunkPos{1, 2, 3},
#   Offsets: []protocol.SubChunkOffset{{-1, 0, 1}}}
V1001 = bytes.fromhex("0001ff0001010000000200000003000000")

GOLDENS = [
    pytest.param(
        v975.SubChunkRequestPacket(
            dimension_type=0,
            center_pos=v975.SubChunkPos(x=1, y=2, z=3),
            sub_chunk_pos_offsets=[v975.SubChunkPacket.SubChunkPosOffset(x=-1, y=0, z=1)],
        ),
        V975,
        id="v975",
    ),
    pytest.param(
        v1001.SubChunkRequestPacket(
            dimension_type=0,
            sub_chunk_pos_offsets=[v1001.SubChunkPacket.SubChunkPosOffset(x=-1, y=0, z=1)],
            center_pos=v1001.SubChunkPos(x=1, y=2, z=3),
        ),
        V1001,
        id="v1001",
    ),
]


@pytest.mark.parametrize("version", [v975, v1001], ids=lambda version: version.__name__.rpartition(".")[2])
def test_sub_chunk_request_is_packet_175(version):
    assert version.PACKETS[175] is version.SubChunkRequestPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_sub_chunk_request_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_sub_chunk_request_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_a_v975_sub_chunk_request_does_not_decode_as_a_v1001_one():
    with pytest.raises(ValueError, match="at byte"):
        v1001.SubChunkRequestPacket.from_bytes(V975)
